function renderHardware(){const q=pageState.q||'',rows=db.hardware.filter(h=>!q||Object.values(h).join(' ').toLowerCase().includes(q.toLowerCase()));$('content').innerHTML=head('Hardware Faults','Track faulty hardware material, its branch site and the reported issue.',`<button class="btn" data-action="open-hardware">${icon('plus')} Report Fault</button>`)+toolbar(`<input data-filter="q" value="${esc(q)}" placeholder="Search hardware, branch or issue..."><button class="btn secondary" data-action="export-hardware">${icon('download')} Export</button>`)+`<section class="card panel table-wrap"><table class="table"><thead><tr><th>Hardware Material</th><th>Hardware Name</th><th>Branch Site</th><th>Issue</th><th>Status</th><th>Actions</th></tr></thead><tbody>${rows.map(h=>`<tr><td>${esc(h.material)}</td><td>${esc(h.name)}</td><td>${esc(h.branch)}</td><td>${esc(h.issue)}</td><td>${badge(h.status)}</td><td>${recordActions('hardware',h.id)}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">No hardware faults found.</td></tr>'}</tbody></table></section>`}
function openHardware(id){const h=db.hardware.find(x=>x.id===id);modal(`<div class="modal-head"><h3>${h?'Edit':'Report'} Hardware Fault</h3><button class="close" data-action="close-modal">×</button></div><div class="form-grid"><div class="field"><label>Hardware Material *</label><input id="hMaterial" value="${esc(h?.material||'')}" placeholder="e.g. Router, Laptop, UPS"></div><div class="field"><label>Hardware Name *</label><input id="hName" value="${esc(h?.name||'')}" placeholder="Asset or device name"></div><div class="field"><label>Branch Site *</label><select id="hBranch"><option value="">Select branch site</option>${db.projects.filter(p=>p.status==='Active').map(p=>`<option value="${esc(p.branch)}" ${h?.branch===p.branch?'selected':''}>${esc(p.branch)} (${esc(p.code)})</option>`).join('')}</select></div><div class="field"><label>Status</label><select id="hStatus"><option ${h?.status==='Open'||!h?'selected':''}>Open</option><option ${h?.status==='Under Repair'?'selected':''}>Under Repair</option><option ${h?.status==='Resolved'?'selected':''}>Resolved</option></select></div><div class="field full"><label>What is the issue? *</label><textarea id="hIssue" placeholder="Describe the fault or damage">${esc(h?.issue||'')}</textarea></div></div><div class="actions"><button class="btn secondary" data-action="close-modal">Cancel</button><button class="btn" data-action="save-hardware" data-id="${id||''}">Save Fault</button></div>`)}
function saveHardware(id){const record={id:id||uid('hardware'),material:$('hMaterial').value.trim(),name:$('hName').value.trim(),branch:$('hBranch').value,issue:$('hIssue').value.trim(),status:$('hStatus').value};if(!record.material||!record.name||!record.branch||!record.issue){notify('Hardware material, name, branch site and issue are required.','error');return}if(id)Object.assign(db.hardware.find(x=>x.id===id),record);else{db.hardware.push(record);activity(`reported a hardware fault for ${record.name}`)}saveDatabase();closeModal();renderHardware();notify('Hardware fault saved.')}
