function clone(value){return JSON.parse(JSON.stringify(value))} function mergeSeed(saved){const base=clone(seed);const result={...base,...(saved||{})};Object.keys(base).forEach(key=>{if(Array.isArray(base[key]))result[key]=Array.isArray(saved?.[key])?saved[key]:base[key];else result[key]={...base[key],...(saved?.[key]||{})}});return result}
function migrateDatabase(saved){const data=mergeSeed(saved);delete data.formFolders;delete data.customFields;data.settings.logo=data.settings.logo||data.logo||CONFIG.logo;data.simHardware=data.simHardware||[];data.users=data.users.map(u=>({...u,id:u.id||uid('user'),mobile:String(u.mobile||'').replace(/\D/g,'').replace(/^91(\d{10})$/,'$1'),email:String(u.email||'').trim().toLowerCase()}));return data}
function isSupabaseReady(){return Boolean(window.TeamOpsSupabase?.configured && window.TeamOpsSupabase.client && window.TeamOpsDatabase);} 
async function loadDatabaseFromSupabase(){
  if(!isSupabaseReady()){
    db = migrateDatabase(clone(seed));
    return;
  }
  try {
    const [profiles, projects, attendance, work, materials, simHardware, hardware] = await Promise.all([
      window.TeamOpsDatabase.list('profiles', {}, { select: 'id, full_name, employee_id, email, mobile, department, project, designation, status, email_verified, last_login_at, role:roles(name)' }),
      window.TeamOpsDatabase.list('projects', {}, { select: 'id, name, code, status, branch_id, created_at' }),
      window.TeamOpsDatabase.list('attendance', {}, { select: 'id, profile_id, attendance_date, status, remark' }),
      window.TeamOpsDatabase.list('dailyWork', {}, { select: '*' }),
      window.TeamOpsDatabase.list('materials', {}, { select: 'id, user_name, project_name, material_name, quantity, priority, status, remark, created_by, created_at' }),
      window.TeamOpsDatabase.list('simCards', {}, { select: 'id, sim_number, mobile_number, provider, assigned_to, project_id, status, remarks, created_at' }),
      window.TeamOpsDatabase.list('hardware', {}, { select: 'id, asset_id, device_type, brand, model, assigned_to, project_id, status, condition, remarks, created_at' })
    ]);

    const projectLookup = new Map((projects || []).map(project => [project.id, project]));
    const profileLookup = new Map((profiles || []).map(profile => [profile.id, profile]));

    db = {
      users: (profiles || []).map(profile => ({
        id: profile.id,
        name: profile.full_name || profile.email || 'Unknown user',
        loginId: profile.email || profile.employee_id || profile.id,
        role: profile.role?.name || 'Employee',
        mobile: profile.mobile || '',
        email: profile.email || '',
        status: profile.status || 'Active',
        employeeId: profile.employee_id || '',
        designation: profile.designation || '',
        department: profile.department || '',
        project: profile.project || '',
        password: 'demo123',
        emailVerified: Boolean(profile.email_verified),
        lastLoginAt: profile.last_login_at || ''
      })),
      projects: (projects || []).map(project => ({
        id: project.id,
        project: project.name || 'Unknown Project',
        code: project.code || '',
        branch: project.branch_id || '',
        projectType: project.name || '',
        status: project.status || 'Active'
      })),
      work: (work || []).map(item => {
        const profile = profileLookup.get(item.profile_id) || {};
        const project = projectLookup.get(item.project_id) || {};
        return {
          ...(item.details && typeof item.details === 'object' && !Array.isArray(item.details) ? item.details : {}),
          id: item.id,
          date: item.work_date || item.details?.date || '',
          engineer: profile.full_name || item.details?.engineer || 'Unknown engineer',
          project: project.name || item.details?.project || '',
          code: project.code || item.details?.code || '',
          branch: project.branch_id || item.details?.branch || '',
          type: item.category || item.details?.type || 'Installation',
          status: item.status || item.details?.status || 'Pending',
          remark: item.details?.remark || item.remarks || item.details?.siteRemark || item.description || ''
        };
      }),
      attendance: (attendance || []).map(item => ({
        id: item.id,
        date: item.attendance_date || '',
        user: profileLookup.get(item.profile_id)?.full_name || 'Unknown employee',
        status: item.status || 'Present',
        remark: item.remark || ''
      })),
      materials: (materials || []).map(item => ({
        id: item.id,
        date: item.created_at ? item.created_at.slice(0, 10) : '',
        user: item.user_name || 'Unknown user',
        project: item.project_name || '',
        material: item.material_name || '',
        createdBy: item.created_by || '',
        qty: Number(item.quantity || 0),
        priority: item.priority || 'Normal',
        status: item.status || 'Pending',
        remark: item.remark || ''
      })),
      simHardware: (simHardware || []).map(item => ({
        id: item.id,
        type: 'SIM',
        asset: item.sim_number || '',
        number: item.sim_number || '',
        mobile: item.mobile_number || '',
        employee: profileLookup.get(item.assigned_to)?.full_name || '',
        project: projectLookup.get(item.project_id)?.name || '',
        status: item.status || 'Available',
        remark: item.remarks || '',
        photo: ''
      })),
      hardware: (hardware || []).map(item => ({
        id: item.id,
        material: item.device_type || '',
        name: item.model || item.brand || '',
        branch: projectLookup.get(item.project_id)?.name || '',
        issue: item.remarks || item.condition || '',
        status: item.status || 'Open'
      })),
      activities: [],
      defects: [],
      settings: { logo: CONFIG.logo, theme: 'light' }
    };

    const uiPreferences = JSON.parse(localStorage.getItem('teamOps_ui_preferences') || '{}');
    if (uiPreferences.settings) db.settings = { ...db.settings, ...uiPreferences.settings };
    if (uiPreferences.theme) db.settings.theme = uiPreferences.theme;
  } catch (error) {
    db = migrateDatabase(clone(seed));
    notify('Supabase data could not be loaded. The app switched to the safe demo state.','error');
  }
}
async function syncDatabaseToSupabase(){
  if(!isSupabaseReady() || !Array.isArray(db?.users)) return;
  try {
    const operations = [
      ['profiles', db.users.map(user => ({ id: user.id, full_name: user.name, employee_id: user.employeeId || user.loginId, email: user.email, mobile: user.mobile, department: user.department || null, project: user.project || null, designation: user.designation || null, status: user.status || 'Active', email_verified: Boolean(user.emailVerified), last_login_at: user.lastLoginAt || null, role_id: null })), true],
      ['projects', db.projects.map(project => ({ id: project.id, name: project.project, code: project.code, status: project.status || 'Active' })), false],
      ['attendance', db.attendance.map(item => ({ id: item.id, profile_id: item.profileId || null, attendance_date: item.date, status: item.status, remark: item.remark || null, created_by: item.createdBy || item.profileId || null })), false],
      ['dailyWork', db.work.map(item => ({ id: item.id, profile_id: item.profileId || null, project_id: (db.projects.find(p=>p.project===item.project)||{}).id || null, work_date: item.date, category: item.type, description: item.remark || item.project || '', status: item.status, remarks: item.remark || null, details: Object.fromEntries(Object.entries(item).filter(([key]) => !['id','profileId','supabaseId'].includes(key))) })), false],
      ['materials', db.materials.map(item => ({ id: item.id, user_name: item.user, project_name: item.project, material_name: item.material, quantity: item.qty, priority: item.priority || 'Normal', status: item.status, remark: item.remark || null, created_by: item.createdBy || null })), false],
      ['hardware', db.hardware.map(item => ({ id: item.id, asset_id: item.id, device_type: item.material || 'Hardware', model: item.name || '', project_id: null, status: item.status || 'Open', remarks: item.issue || null })), false]
    ];

    for (const [collectionName, rows, skipUpsert] of operations) {
      if (!Array.isArray(rows) || !rows.length) continue;
      if (skipUpsert) continue;
      const resource = window.TeamOpsDatabase?.[collectionName];
      if (!resource) continue;
      for (const row of rows) {
        if (!row.id) continue;
        try {
          const existing = await resource.get(row.id).catch(() => null);
          if (existing) await resource.update(row.id, row);
          else await resource.create(row);
        } catch (error) {
          console.warn(`Database sync failed for ${collectionName}:`, error);
        }
      }
    }
  } catch (error) {
    console.warn('Database sync to Supabase failed:', error);
  }
}
function loadDatabase(){
  try {
    const uiPreferences = JSON.parse(localStorage.getItem('teamOps_ui_preferences') || '{}');
    if (isSupabaseReady()) {
      db = migrateDatabase(clone(seed));
      if (uiPreferences.settings) db.settings = { ...db.settings, ...uiPreferences.settings };
      if (uiPreferences.theme) db.settings.theme = uiPreferences.theme;
      loadDatabaseFromSupabase();
      return;
    }
    db = migrateDatabase(clone(seed));
    if (uiPreferences.settings) {
      db.settings = { ...db.settings, ...uiPreferences.settings };
    }
    if (uiPreferences.theme) {
      db.settings.theme = uiPreferences.theme;
    }
  } catch (error) {
    db = clone(seed);
    notify('Saved UI preferences were invalid. A safe default state was loaded.','error');
  }
}
function saveDatabase(){
  try {
    const preferences = {
      theme: db?.settings?.theme || 'light',
      settings: {
        logo: db?.settings?.logo || CONFIG.logo,
        theme: db?.settings?.theme || 'light'
      }
    };
    localStorage.setItem('teamOps_ui_preferences', JSON.stringify(preferences));
    if (isSupabaseReady()) {
      syncDatabaseToSupabase();
    }
  } catch (error) {
    notify('Could not save non-critical UI preferences. The app will continue in-memory for this session.','error');
  }
}
function resetDatabase(){if(!allow('settings'))return;if(!confirm('Reset all local data to the demo starting state? This cannot be undone.'))return;db=clone(seed);saveDatabase();logout()}
