const api={get:(collection)=>clone(db[collection]||[]),post:(collection,item)=>{db[collection].push(item);saveDatabase();return item},put:(collection,id,patch)=>{const item=db[collection].find(x=>x.id===id);if(item)Object.assign(item,patch);saveDatabase();return item},delete:(collection,id)=>{if(!db[collection])return;db[collection]=db[collection].filter(x=>x.id!==id);saveDatabase()}};
function notify(message,type='success'){const t=$('toast');if(!t)return;t.textContent=message;t.className=`toast ${type}`;clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.add('hidden'),3200)}
function currentUser(){return db?.users.find(u=>u.loginId===session?.loginId)} function isAM(){return session?.role==='Admin'||session?.role==='Assistant Manager'||session?.role==='Team Lead'} function isTL(){return session?.role==='Team Lead'} function isEmployee(){return session?.role==='Employee'}
const permissions={dashboard:['Assistant Manager','Team Lead','Employee'],daily:['Assistant Manager','Team Lead','Employee'],attendance:['Assistant Manager','Team Lead','Employee'],projects:['Assistant Manager','Team Lead','Employee'],materials:['Assistant Manager','Team Lead','Employee'],sim:['Assistant Manager','Team Lead','Employee'],hardware:['Assistant Manager','Team Lead','Employee'],team:['Assistant Manager','Team Lead','Employee'],reports:['Assistant Manager','Team Lead'],users:['Assistant Manager','Team Lead'],settings:['Assistant Manager','Team Lead'],help:['Assistant Manager','Team Lead']};
function allow(action){const permitted=isAM()||isTL()||(!isEmployee()&&action==='recordCreate');if(action==='settings'&&!isAM()||action==='userDelete'&&isEmployee()||action==='recordEdit'&&isEmployee()||action==='recordDelete'&&isEmployee()||action==='export'&&isEmployee()||action==='projectDelete'&&!isAM()||action==='defectEdit'&&!isAM()){notify('You do not have permission for this action.','error');return false}if(['userCreate','userEdit','projectEdit','excelImport'].includes(action)&&!permitted){notify('You do not have permission for this action.','error');return false}return true}
