function navigate(page,resetState=true){if(!routeAllowed(page)){notify('This area is not available for your role.','error');return}const samePage=currentPage===page;currentPage=page;if(resetState&&!samePage)pageState={};renderNav();$('pageTitle').textContent=navItems().find(x=>x[0]===page)?.[2]||'Team Operations';$('pageSub').textContent='Internal operations workspace';$('sidebar').classList.remove('open');({dashboard:renderDashboard,daily:renderDaily,attendance:renderAttendance,projects:renderProjects,materials:renderMaterials,sim:renderSim,hardware:renderHardware,team:renderTeam,reports:renderReports,users:renderUsers,settings:renderSettings,help:renderDefects}[page]||renderDashboard)();applyRoleRestrictions()}
