function kpi(label,value,meta,ic){return `<div class="card kpi"><div class="kpi-head"><span class="kpi-icon">${icon(ic)}</span></div><div class="kpi-label">${label}</div><div class="kpi-number">${value}</div><div class="kpi-meta">${meta}</div></div>`}
function badge(value){const cls=String(value).toLowerCase().includes('completed')||String(value).toLowerCase().includes('present')||String(value).toLowerCase().includes('approved')||String(value).toLowerCase().includes('active')?'success':String(value).toLowerCase().includes('pending')||String(value).toLowerCase().includes('progress')||String(value).toLowerCase().includes('leave')?'warning':String(value).toLowerCase().includes('rejected')||String(value).toLowerCase().includes('closed')||String(value).toLowerCase().includes('absent')?'danger':'info';return `<span class="badge ${cls}">${esc(value)}</span>`}
function toolbar(fields){return `<div class="toolbar">${fields}</div>`}
function renderDaily(){const q=pageState.q||'',date=pageState.date||'',engineer=pageState.engineer||'',project=pageState.project||'',status=pageState.status||'';let rows=db.work.filter(w=>(!q||Object.values(w).join(' ').toLowerCase().includes(q.toLowerCase()))&&(!date||w.date===date)&&(!engineer||w.engineer===engineer)&&(!project||w.project===project)&&(!status||w.status===status));$('content').innerHTML=head('Daily Work','Capture and review installation, site visit, troubleshooting and maintenance work.',`<button class="btn" data-action="open-work">${icon('plus')} Add Work</button>`)+toolbar(`<input data-filter="q" value="${esc(q)}" placeholder="Search work..."><input type="date" data-filter="date" value="${date}"><select data-filter="engineer"><option value="">All engineers</option>${db.users.map(u=>`<option ${engineer===u.name?'selected':''}>${esc(u.name)}</option>`).join('')}</select><select data-filter="project"><option value="">All projects</option>${unique(db.projects.map(p=>p.project)).map(p=>`<option ${project===p?'selected':''}>${esc(p)}</option>`).join('')}</select><select data-filter="status"><option value="">All statuses</option>${CONFIG.workStatuses.map(s=>`<option ${status===s?'selected':''}>${s}</option>`).join('')}<option value="">All statuses</option></select><button class="btn secondary" data-action="export-work">${icon('download')} Export</button>`)+`<section class="card panel table-wrap"><table class="table"><thead><tr><th>Date</th><th>Engineer</th><th>Project / Site</th><th>Branch Code</th><th>Branch Name</th><th>Type</th><th>Status</th><th>Actions</th></tr></thead><tbody>${rows.map(w=>`<tr><td>${formatDate(w.date)}</td><td>${esc(w.engineer)}</td><td>${esc(w.project)}</td><td>${esc(w.code)}</td><td>${esc(w.branch)}</td><td>${esc(w.type)}</td><td>${badge(w.status)}</td><td>${recordActions('work',w.id)}</td></tr>`).join('')||'<tr><td colspan="8" class="empty">No daily work matches these filters.</td></tr>'}</tbody></table></section>`}
function refreshBranches(project=$('wProject')?.value,code=''){const select=$('wCode');if(!select)return;const options=db.projects.filter(p=>p.status==='Active'&&p.project===project);select.innerHTML='<option value="">Select branch code</option>'+options.map(p=>`<option value="${esc(p.code)}" ${p.code===code?'selected':''}>${esc(p.code)}</option>`).join('');setBranchName()}
