function openUploadedSimPhoto(){const image=$('sPhotoPreview')?.querySelector('img');if(!image)return;modal(`<div class="modal-head"><h3>SIM Card Image</h3><button class="close" data-action="close-modal">×</button></div><div class="sim-photo-fullscreen"><img src="${esc(image.src)}" alt="SIM card image fullscreen"></div><div class="actions"><button class="btn" data-action="close-modal">Close</button></div>`)}
function simBackend(){const client=window.TeamOpsSupabase?.configured?window.TeamOpsSupabase.client:null;if(!client)return null;return new Proxy(client,{get(target,key){if(key!=='from')return target[key];return table=>{const builder=target.from(table);if(table!=='sim_cards')return builder;return new Proxy(builder,{get(query,method){if(method!=='insert'&&method!=='update')return query[method];return payload=>{const clean={...payload};delete clean.created_by;return query[method](clean)}}})}}})}
function normalizeIccid(value){return String(value||'').trim()}
function isValidIccid(value){return Boolean(normalizeIccid(value))}
function simLocalRecord(row,photo=''){const employee=db.users.find(user=>user.profileId===row.assigned_to||user.id===row.assigned_to),project=db.projects.find(item=>item.id===row.project_id);return{id:row.id,type:'SIM',asset:row.sim_number,number:row.sim_number,mobile:row.mobile_number||'',employee:employee?.name||'',employeeId:row.assigned_to||'',project:project?.project||'',projectId:row.project_id||'',status:row.status||'Available',remark:row.remarks||'',imagePath:row.image_path||'',photo}}
async function syncSimFromSupabase(){const client=simBackend();if(!client)return;try{const {data,error}=await client.from('sim_cards').select('*').order('created_at',{ascending:false});if(error)throw error;const records=await Promise.all((data||[]).map(async row=>{let photo='';if(row.image_path){const signed=await client.storage.from('sim-card-photos').createSignedUrl(row.image_path,3600);photo=signed.data?.signedUrl||''}return simLocalRecord(row,photo)}));const remoteNumbers=new Set(records.map(item=>item.number));db.simHardware=db.simHardware.filter(item=>!remoteNumbers.has(normalizeIccid(item.number||item.asset||item.mobile)));db.simHardware.push(...records.map(item=>({...item,supabaseId:item.id})));saveDatabase();if(currentPage==='sim')renderSim()}catch(error){notify(`SIM cloud sync failed: ${error.message||'check Supabase setup'}`,'error')}}
async function removeSim(id){if(!confirm('Delete this SIM card? This cannot be undone.'))return;const client=simBackend(),record=db.simHardware.find(item=>item.id===id||item.supabaseId===id);try{if(client){if(record?.imagePath)await client.storage.from('sim-card-photos').remove([record.imagePath]);const result=await client.from('sim_cards').delete().eq('id',record?.supabaseId||id);if(result.error)throw result.error}db.simHardware=db.simHardware.filter(item=>item.id!==id&&item.supabaseId!==id);saveDatabase();renderSim();notify(client?'SIM details deleted from Supabase.':'SIM details deleted locally.')}catch(error){notify(error.message||'SIM details could not be deleted.','error')}}
async function saveSim(id){const old=db.simHardware.find(x=>x.id===id),number=normalizeIccid($('sAsset').value),file=$('sPhoto').files[0],record={id:id||uid('asset'),type:'SIM',asset:number,number,mobile:old?.mobile||'',imei:old?.imei||'',employee:$('sEmployee').value,project:$('sProject').value,status:$('sStatus').value,remark:$('sRemark').value.trim(),photo:old?.photo||''};if(!isValidIccid(number)){notify('Enter a valid ICCID/SIM number with 18 to 22 digits and a valid checksum.','error');return}if(db.simHardware.some(item=>item.id!==id&&normalizeIccid(item.number||item.asset||item.mobile)===number)){notify('This SIM card number is already registered.','error');return}const client=simBackend();try{if(client){const currentUserId=session?.userId||currentUser()?.profileId||currentUser()?.id,assignedTo=db.users.find(user=>user.name===record.employee),project=db.projects.find(item=>item.project===record.project),payload={sim_number:number,mobile_number:record.mobile||null,provider:'SIM',assigned_to:assignedTo?.profileId||assignedTo?.id||null,project_id:project?.id&&/^[0-9a-f-]{36}$/i.test(project.id)?project.id:null,status:record.status,remarks:record.remark||null,created_by:currentUserId&&/^[0-9a-f-]{36}$/i.test(currentUserId)?currentUserId:null,updated_at:new Date().toISOString()};if(file){const extension=(file.name.split('.').pop()||'jpg').toLowerCase(),path=`${currentUserId||'unassigned'}/${number}-${Date.now()}.${extension}`,upload=await client.storage.from('sim-card-photos').upload(path,file,{contentType:file.type||'image/jpeg',upsert:false});if(upload.error)throw upload.error;payload.image_path=path}const request=id?client.from('sim_cards').update(payload).eq('id',id).select().single():client.from('sim_cards').insert(payload).select().single(),result=await request;if(result.error)throw result.error;record.id=result.data.id;record.supabaseId=result.data.id;record.imagePath=result.data.image_path||'';if(file){const signed=await client.storage.from('sim-card-photos').createSignedUrl(record.imagePath,3600);record.photo=signed.data?.signedUrl||''}if(id)Object.assign(old,record);else db.simHardware.push(record);saveDatabase();closeModal();renderSim();notify('SIM details saved to Supabase.');return}const finish=()=>{if(id)Object.assign(old,record);else{db.simHardware.push(record);activity('added a SIM card')}saveDatabase();closeModal();renderSim();notify('SIM details saved locally.')};if(file){const reader=new FileReader();reader.onload=()=>{record.photo=reader.result;finish()};reader.readAsDataURL(file)}else finish()}catch(error){notify(error.message||'SIM details could not be saved.','error')}}
function renderTeam(){const q=pageState.q||'',role=pageState.role||'',status=pageState.status||'';const rows=db.users.filter(u=>(!q||Object.values({...u,password:undefined}).join(' ').toLowerCase().includes(q.toLowerCase()))&&(!role||u.role===role)&&(!status||u.status===status));$('content').innerHTML=head('Team','Directory of employees and access roles.',isAM()?`<button class="btn" data-action="open-user">${icon('plus')} Add User</button>`:'')+toolbar(`<input data-filter="q" value="${esc(q)}" placeholder="Search team..."><select data-filter="role"><option value="">All roles</option>${CONFIG.roles.map(v=>`<option ${role===v?'selected':''}>${v}</option>`).join('')}</select><select data-filter="status"><option value="">All statuses</option><option ${status==='Active'?'selected':''}>Active</option><option ${status==='Inactive'?'selected':''}>Inactive</option></select>`)+`<section class="card panel table-wrap"><table class="table"><thead><tr><th>Name</th><th>Role</th><th>Login ID</th><th>Email</th><th>Mobile</th><th>Status</th><th>Actions</th></tr></thead><tbody>${rows.map(u=>`<tr><td><button class="btn secondary small" data-action="view-user" data-id="${u.id}">${esc(u.name)}</button></td><td>${esc(u.role)}</td><td>${esc(u.loginId)}</td><td>${esc(u.email)}</td><td>${esc(u.mobile||'-')}</td><td>${badge(u.status)}</td><td>${isAM()?recordActions('user',u.id):''}</td></tr>`).join('')||'<tr><td colspan="7" class="empty">No team members match these filters.</td></tr>'}</tbody></table></section>`}
