function normalizeMonitorStatus(value){const status=String(value||'').trim();if(!status)return 'Issue';const normalized=status.toLowerCase();if(normalized.includes('completed')||normalized.includes('complete')||normalized.includes('closed'))return 'Completed';if(normalized.includes('in progress')||normalized.includes('progress'))return 'In Progress';if(normalized.includes('pending')||normalized.includes('awaiting'))return 'Pending';return 'Issue'}
const WORK_DETAIL_FIELDS=[['srNo','Sr No'],['date','Date'],['engineer','Engineer'],['siteEngineerName','Site Engineer Name'],['callTakenBy','Call Taken By'],['engineerNumber','Engineer Number'],['project','Project / Site'],['projectType','Project Type'],['code','Branch Code'],['branch','Branch Name'],['type','Call Type'],['status','Work Status'],['maps','Google Maps Link'],['state','State'],['longitude','Longitude'],['latitude','Latitude'],['simName','SIM Name'],['simNumber','SIM Card Number'],['linkIp','Link IP'],['mac','Link Device MAC ID'],['wVaultTam','Vault Tamper'],['wCashTam','Cash Tamper'],['wMainDoorTam','Main Door Tamper'],['wNglDoorTam','NGL Door Tamper'],['inTime','In Time'],['outTime','Out Time'],['softQc','Soft QC'],['configureStatus','Configure Status'],['siteRemark','Site Remark'],['remark','Remark'],['handover','Handover Status']];
function workRecordKeys(records){const known=WORK_DETAIL_FIELDS.map(([key])=>key),internal=new Set(['id','profileId','supabaseId']);return [...known,...unique(records.flatMap(record=>Object.keys(record||{}))).filter(key=>!internal.has(key)&&!known.includes(key))]}
function workFieldLabel(key){return WORK_DETAIL_FIELDS.find(([field])=>field===key)?.[1]||key.replace(/([A-Z])/g,' $1').replace(/^./,letter=>letter.toUpperCase())}
