function renderSettings(){if(!isAM()){notify('Assistant Manager access required.','error');return}const u=currentUser();$('content').innerHTML=head('Settings','Profile, logo, and local data management.')+`<section class="card panel"><h3>My Profile</h3><div class="form-grid"><div class="field"><label>Login ID</label><input readonly value="${esc(u.loginId)}"></div><div class="field"><label>Email</label><input readonly value="${esc(u.email)}"></div><div class="field"><label>Registered Mobile</label><input id="settingsMobile" maxlength="10" value="${esc(u.mobile)}"></div></div><div class="actions"><button class="btn" data-action="save-settings-profile">Save Mobile Number</button></div></section><section class="card panel" style="margin-top:14px"><h3>Application Logo</h3><p class="muted">The bundled ZYGAL logo is used by default. Upload a replacement when needed.</p><input id="logoFile" type="file" accept="image/png,image/jpeg,image/webp"><div class="actions"><button class="btn secondary" data-action="upload-logo">${icon('upload')} Upload Logo</button><button class="btn danger" data-action="remove-logo">Remove Logo</button></div></section><section class="card panel" style="margin-top:14px"><h3>Data Management</h3><p class="muted">LocalStorage belongs to this browser only. It is not shared with other employees.</p><div class="actions"><button class="btn secondary" data-action="export-db">${icon('download')} Export Backup</button><label class="btn secondary">${icon('upload')} Import Backup<input id="dbFile" type="file" accept="application/json" hidden></label><button class="btn danger" data-action="reset-db">Reset Demo Data</button></div></section>`}
