function renderActivities(){const q=pageState.q||'',rows=db.activities.slice().reverse().filter(a=>!q||Object.values(a).join(' ').toLowerCase().includes(q.toLowerCase()));$('content').innerHTML=head('Recent Activities','Review the latest changes made across the operations workspace.')+toolbar(`<input data-filter="q" value="${esc(q)}" placeholder="Search activities...">`)+`<section class="card panel activity-feed">${rows.map(a=>`<div class="activity"><span class="activity-icon">${icon('work',14)}</span><div><b>${esc(a.user)}</b><span class="activity-action">${esc(a.text)}</span><small class="muted">${esc(a.time||'')}</small></div></div>`).join('')||'<div class="empty">No activities match your search.</div>'}</section>`}
