function saveProfile(){const user=currentUser(),name=$('profileName').value.trim(),country=$('profileCountry').value,m=$('profileMobile').value.replace(/\D/g,'');if(!name){notify('Full name is required.','error');return}if(country==='+91'&&!/^[6-9]\d{9}$/.test(m)){notify('For +91, mobile number must contain 10 digits and start with 6, 7, 8 or 9.','error');return}if(country!=='+91'&&(m.length<7||m.length>15)){notify('Mobile number must contain between 7 and 15 digits for the selected country.','error');return}if(db.users.some(x=>x.id!==user.id&&x.mobile===m&&(x.mobileCountryCode||'+91')===country)){notify('This mobile number is already registered to another user.','error');return}user.name=name;user.mobile=m;user.mobileCountryCode=country;saveDatabase();$('userName').textContent=name;$('sidebarName').textContent=name;$('avatar').textContent=name.charAt(0).toUpperCase();$('sidebarAvatar').textContent=name.charAt(0).toUpperCase();closeModal();notify('Profile updated.')}
