	function viewSimCard(id){const s=db.simHardware.find(x=>x.id===id);if(!s)return;modal(`<div class="modal-head"><h3>SIM Card Details</h3><button class="close" data-action="close-modal">×</button></div><div class="sim-detail">${s.photo?`<img class="sim-detail-photo" src="${esc(s.photo)}" alt="${esc(s.name||'SIM photo')}">`:'<div class="sim-detail-photo sim-detail-empty">No photo</div>'}<div class="sim-detail-fields"><div><span>SIM Name</span><b>${esc(s.name||'-')}</b></div><div><span>SIM Card No.</span><b>${esc(s.number||s.mobile||'-')}</b></div><div><span>Type</span><b>${esc(s.simType||'SIM')}</b></div><div><span>Branch Site</span><b>${esc(s.branch||s.project||'-')}</b></div></div></div><div class="actions"><button class="btn" data-action="close-modal">Close</button></div>`)}
	function viewSim(id){const s=db.simHardware.find(x=>x.id===id);if(!s)return;modal(`<div class="modal-head"><h3>SIM Details</h3><button class="close" data-action="close-modal">×</button></div><div class="sim-detail">${s.photo?`<button class="sim-photo-button" data-action="view-sim-photo" data-id="${id}" title="Open SIM image fullscreen" aria-label="Open SIM image fullscreen"><img class="sim-detail-photo" src="${esc(s.photo)}" alt="SIM card image"><span>${icon('eye',14)} View fullscreen</span></button>`:'<div class="sim-detail-photo sim-detail-empty">No image</div>'}<div class="sim-detail-fields"><div><span>Type</span><b>SIM</b></div><div><span>SIM Card No.</span><b>${esc(s.number||s.asset||s.mobile||'-')}</b></div><div><span>Employee</span><b>${esc(s.employee||'Unassigned')}</b></div><div><span>Project</span><b>${esc(s.project||'Unassigned')}</b></div><div><span>Status</span><b>${badge(s.status||'Available')}</b></div><div><span>Remark</span><b>${esc(s.remark||'-')}</b></div></div></div><div class="actions"><button class="btn" data-action="close-modal">Close</button></div>`)}
	function viewSimPhoto(id){const s=db.simHardware.find(x=>x.id===id);if(!s?.photo)return;modal(`<div class="modal-head"><h3>SIM Card Image</h3><button class="close" data-action="close-modal">×</button></div><div class="sim-photo-fullscreen"><img src="${esc(s.photo)}" alt="SIM card image fullscreen"></div><div class="actions"><button class="btn secondary" data-action="view-sim" data-id="${id}">Back to details</button><button class="btn" data-action="close-modal">Close</button></div>`)}
function unique(values){return [...new Set(values.filter(Boolean))]} function formatDate(value){if(!value)return '-';return new Date(`${value}T00:00:00`).toLocaleDateString(undefined,{day:'2-digit',month:'short',year:'numeric'})}
function activity(text){db.activities.push({id:uid('activity'),user:currentUser()?.name||'System',text,time:now()});db.activities=db.activities.slice(-100)}
function removeRecord(type,id){if(type==='sim'&&simBackend()){removeSim(id);return}const map={work:'work',attendance:'attendance',project:'projects',material:'materials',sim:'simHardware',user:'users'};if(type==='user'&&(id===currentUser().id||isTL()))return notify(isTL()?'Team Leads cannot delete users.':'You cannot delete your own account.','error');if(type==='project'&&!allow('projectDelete'))return;if(!confirm('Delete this record? This cannot be undone.'))return;api.delete(map[type],id);navigate(currentPage);notify('Record deleted.')}
function editRecord(type,id){const map={work:openWork,attendance:openAttendance,project:openProject,material:openMaterial,sim:openSim,user:openUser};if(map[type])map[type](id)}
function editHardware(id){openHardware(id)}
function removeHardware(id){if(!confirm('Delete this hardware fault? This cannot be undone.'))return;db.hardware=db.hardware.filter(x=>x.id!==id);saveDatabase();renderHardware();notify('Hardware fault deleted.')}
function exportRows(filename,headers,rows){const csv=[headers,...rows].map(row=>row.map(v=>`"${String(v??'').replace(/"/g,'""')}"`).join(',')).join('\r\n');downloadFile(filename,csv,'text/csv;charset=utf-8')}
function downloadFile(name,data,type){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([data],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500)}
function exportCollection(collection,headers,fields,name){exportRows(`${name}_${today()}.csv`,headers,db[collection].map(item=>fields.map(field=>item[field])));notify('Export downloaded.')}
function downloadSample(){const rows=[['Project Name','Branch Code','Branch Name','Status'],['Bajaj Finserv','BJ001','Pune Main','Active']];exportRows('Project_Site_Bulk_Upload_Sample.csv',rows[0],rows.slice(1));notify('Sample downloaded.')}
async function importProjects(file){if(!allow('excelImport')||!file)return;try{let rows;if(file.name.toLowerCase().endsWith('.csv'))rows=parseCSV(await file.text());else{await loadSheetJS();const wb=XLSX.read(await file.arrayBuffer(),{type:'array'});rows=XLSX.utils.sheet_to_json(wb.Sheets[wb.SheetNames[0]],{header:1,defval:''})}if(rows.length<2)throw Error('The file has no data rows.');const header=rows[0].map(x=>String(x).trim().toLowerCase()),idx={project:header.indexOf('project name'),code:header.indexOf('branch code'),branch:header.indexOf('branch name'),status:header.indexOf('status')};if(Object.values(idx).slice(0,3).some(x=>x<0))throw Error('Required columns are Project Name, Branch Code and Branch Name.');const preview=[],failed=[];rows.slice(1).forEach((row,i)=>{const p=String(row[idx.project]??'').trim(),code=String(row[idx.code]??'').trim(),branch=String(row[idx.branch]??'').trim(),status=String(row[idx.status]??'Active').trim()||'Active';if(!p||!code||!branch)failed.push(`Row ${i+2}: project, branch code and branch name are required.`);else if(!['Active','Inactive'].includes(status))failed.push(`Row ${i+2}: status must be Active or Inactive.`);else preview.push({project:p,code,branch,status})});modal(`<div class="modal-head"><h3>Import Preview</h3><button class="close" data-action="close-modal">×</button></div><p>Valid rows: <b>${preview.length}</b> · Failed rows: <b>${failed.length}</b></p><div class="notice">${failed.length?esc(failed.slice(0,8).join(' ')):'All rows passed validation.'}</div><div class="table-wrap"><table class="table"><thead><tr><th>Project</th><th>Code</th><th>Branch</th><th>Status</th></tr></thead><tbody>${preview.slice(0,20).map(x=>`<tr><td>${esc(x.project)}</td><td>${esc(x.code)}</td><td>${esc(x.branch)}</td><td>${esc(x.status)}</td></tr>`).join('')}</tbody></table></div><div class="actions"><button class="btn secondary" data-action="close-modal">Cancel</button><button class="btn" data-action="commit-import" data-rows="${esc(JSON.stringify(preview))}">Commit ${preview.length} Rows</button></div>`)}catch(error){notify(error.message,'error')}}
function commitImport(rows){const parsed=JSON.parse(rows),seen=new Set(),failed=[];let added=0,updated=0;parsed.forEach(item=>{if(seen.has(item.code.toLowerCase())){failed.push(item.code);return}seen.add(item.code.toLowerCase());const existing=db.projects.find(x=>x.code.toLowerCase()===item.code.toLowerCase());if(existing){Object.assign(existing,item);updated++}else{db.projects.push({id:uid('project'),...item});added++}});saveDatabase();closeModal();renderProjects();notify(`Import complete: ${added} new, ${updated} updated${failed.length?`, ${failed.length} duplicate failed`:''}.`)}
function parseCSV(text){const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i],next=text[i+1];if(c==='"'&&quoted&&next==='"'){cell+='"';i++}else if(c==='"')quoted=!quoted;else if(c===','&&!quoted){row.push(cell.trim());cell=''}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&next==='\n')i++;row.push(cell.trim());if(row.some(x=>x))rows.push(row);row=[];cell=''}else cell+=c}if(cell||row.length){row.push(cell.trim());rows.push(row)}return rows}
function loadSheetJS(){return new Promise((resolve,reject)=>{if(window.XLSX)return resolve();const s=document.createElement('script');s.src='https://cdn.sheetjs.com/xlsx-0.20.3/package/dist/xlsx.full.min.js';s.onload=resolve;s.onerror=()=>reject(Error('Excel library could not load. Use CSV instead.'));document.head.appendChild(s)})}
function openModal(html){$('modalBox').innerHTML=html;$('modal').classList.remove('hidden');$('modalBox').querySelector('input,select,textarea,button')?.focus()}function modal(html){openModal(html)}function closeModal(){$('modal').classList.add('hidden');$('modalBox').innerHTML=''}
function globalSearch(query){const box=$('searchResults'),term=query.trim().toLowerCase();if(!term){box.classList.add('hidden');return}const results=[];const add=(group,label,meta,action)=>{if(`${label} ${meta}`.toLowerCase().includes(term))results.push({group,label,meta,action})};db.users.forEach(u=>add('Employees',u.name,`${u.role} ${u.loginId} ${u.email}`,()=>navigate('team')));db.projects.forEach(p=>add('Projects',p.project,`${p.code} ${p.branch}`,()=>navigate('projects')));db.work.forEach(w=>add('Daily Work',w.project,`${w.engineer} ${w.code} ${w.branch}`,()=>navigate('daily')));db.materials.forEach(m=>add('Materials',m.material,`${m.project} ${m.user}`,()=>navigate('materials')));db.simHardware.forEach(s=>add('SIM / Hardware',s.asset,`${s.employee} ${s.imei}`,()=>navigate('sim')));box.innerHTML=results.slice(0,30).map((r,i)=>`<button data-search-index="${i}"><b>${esc(r.label)}</b><small>${esc(r.group)} · ${esc(r.meta)}</small></button>`).join('')||'<div class="empty">No results found.</div>';box.classList.remove('hidden');window.searchResults=results.slice(0,30)}
function updateFilter(key,value){pageState[key]=value;navigate(currentPage,false)}
function handleAction(target){const action=target.dataset.action,id=target.dataset.id,type=target.dataset.type;switch(action){case'close-modal':closeModal();break;case'logout':logout();break;case'view-profile':viewProfile();break;case'edit-profile':editProfile();break;case'open-work':openWork();break;case'save-work':saveWork(id);break;case'open-attendance':openAttendance();break;case'save-attendance':saveAttendance(id);break;case'open-project':openProject();break;case'edit-record':editRecord(type,id);break;case'delete-record':removeRecord(type,id);break;case'save-project':saveProject(id);break;case'open-material':openMaterial();break;case'save-material':saveMaterial(id);break;case'open-sim':openSim();break;case'save-sim':saveSim(id);break;case'open-user':openUser();break;case'view-user':viewUser(id);break;case'save-user':saveUser(id);break;case'open-defect':openDefect();break;case'save-defect':saveDefect();break;case'save-profile':saveProfile();break;case'save-settings-profile':saveSettingsProfile();break;case'open-forgot':openForgot();break;case'send-otp':sendOtp();break;case'reset-password':resetPassword();break;case'upload-logo':uploadLogo();break;case'remove-logo':if(!confirm('Restore the official Zygal logo? Your uploaded logo will be removed.'))break;db.settings.logo=CONFIG.logo;saveDatabase();setLogo();notify('Default logo restored.');break;case'export-db':exportDatabase();break;case'reset-db':resetDatabase();break;case'run-report':runReport();break;case'download-sample':downloadSample();break;case'clear-dashboard-filters':delete pageState.dateFrom;delete pageState.dateTo;delete pageState.employeeFilter;delete pageState.projectFilter;delete pageState.statusFilter;navigate('reports');break;case'export-report':exportMonitoringReport();break;case'export-work':exportCollection('work',['Date','Engineer','Project','Branch Code','Branch Name','Type','Status','Remark'],['date','engineer','project','code','branch','type','status','remark'],'Daily_Work');break;case'export-attendance':exportCollection('attendance',['Date','Employee','Status','Remark'],['date','user','status','remark'],'Attendance');break;case'export-projects':exportCollection('projects',['Project','Branch Code','Branch Name','Status'],['project','code','branch','status'],'Projects_Sites');break;case'export-materials':exportCollection('materials',['Request ID','Date','Employee','Project','Material','Quantity','Priority','Status','Remark'],['id','date','user','project','material','qty','priority','status','remark'],'Material_Requests');break;case'export-sim':exportCollection('simHardware',['Type','Asset','Mobile','IMEI','Employee','Project','Status','Remark'],['type','asset','mobile','imei','employee','project','status','remark'],'SIM_Hardware');break;case'export-report':exportCollection('work',['Date','Engineer','Project','Branch Code','Branch Name','Type','Status','Remark'],['date','engineer','project','code','branch','type','status','remark'],'Team_Operations_Report');break;case'export-defects':exportCollection('defects',['Date/Time','User','Module','Issue','Correction','Status'],['time','user','module','text','correction','status'],'Defect_History');break;case'commit-import':commitImport(target.dataset.rows);break}}
function viewUser(id){const u=db.users.find(x=>x.id===id);if(!u)return;modal(`<div class="modal-head"><h3>Employee Profile</h3><button class="close" data-action="close-modal">×</button></div><div class="form-grid"><div class="field"><label>Name</label><input readonly value="${esc(u.name)}"></div><div class="field"><label>Role</label><input readonly value="${esc(u.role)}"></div><div class="field"><label>Login ID</label><input readonly value="${esc(u.loginId)}"></div><div class="field"><label>Email</label><input readonly value="${esc(u.email)}"></div><div class="field"><label>Mobile</label><input readonly value="${esc(u.mobile||'-')}"></div></div><div class="actions"><button class="btn" data-action="close-modal">Close</button></div>`)}
function bindEvents(){document.addEventListener('click',e=>{const target=e.target.closest('[data-action]');if(target){e.preventDefault();handleAction(target);return}if(e.target.closest('#sPhotoPreview')){e.preventDefault();openUploadedSimPhoto();return}const nav=e.target.closest('[data-page]');if(nav){e.preventDefault();navigate(nav.dataset.page);return}const result=e.target.closest('[data-search-index]');if(result){const r=window.searchResults?.[Number(result.dataset.searchIndex)];if(r){$('searchResults').classList.add('hidden');$('globalSearch').value='';r.action()}return}if(!e.target.closest('.profile-menu'))closeProfileMenu();if(!e.target.closest('.search'))$('searchResults').classList.add('hidden')});document.addEventListener('input',e=>{if(e.target.id==='globalSearch')globalSearch(e.target.value);if(e.target.dataset.filter){pageState[e.target.dataset.filter]=e.target.value;clearTimeout(window.filterTimer);window.filterTimer=setTimeout(()=>navigate(currentPage),180)}});document.addEventListener('change',e=>{if(e.target.id==='wProject')refreshBranches();if(e.target.id==='wCode')setBranchName();if(e.target.id==='sPhoto')previewAssetPhoto(e.target.files[0]);if(e.target.id==='projectFile')importProjects(e.target.files[0]);if(e.target.id==='dbFile')importDatabaseFile(e.target.files[0]);if(e.target.dataset.filter)navigate(currentPage)});document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeModal();closeProfileMenu()}});$('loginForm').addEventListener('submit',e=>{e.preventDefault();login()});$('mobileMenu').addEventListener('click',()=>$('sidebar').classList.toggle('open'));$('profileTrigger').addEventListener('click',toggleProfileMenu);$('modal').addEventListener('click',e=>{if(e.target===$('modal'))closeModal()})}
function importDatabaseFile(file){if(!file)return;const reader=new FileReader();reader.onload=()=>{try{db=migrateDatabase(JSON.parse(reader.result));saveDatabase();enter();notify('Backup imported.')}catch{notify('That backup file is invalid.','error')}};reader.readAsText(file)}
function openWork(id){if(!routeAllowed('daily'))return;const w=db.work.find(x=>x.id===id),projects=db.projects.filter(p=>p.status!=='Inactive'),projectTypes=unique(projects.map(p=>p.projectType||p.branch));modal(`<div class="modal-head"><div><h3>${w?'Edit':'Add'} Daily Work</h3><p class="muted">Complete the site call details in one entry.</p></div><button class="close" data-action="close-modal">×</button></div><div class="work-form-progress"><span>Daily Work Entry</span><span>8 sections</span></div><div class="work-sections"><section class="work-section"><div class="work-section-title"><b>1</b><div><h4>Basic Information</h4><p>Who, what, and where this call belongs to.</p></div></div><div class="form-grid"><div class="field"><label>Sr No *</label><input id="wSrNo" value="${esc(w?.srNo||'')}" placeholder="e.g. 001"></div><div class="field"><label>Date *</label><input id="wDate" type="date" value="${w?.date||today()}"></div><div class="field"><label>Call Type *</label><select id="wType"><option value="">Select call type</option>${CONFIG.workTypes.map(v=>`<option ${w?.type===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label>Project *</label><select id="wProject"><option value="">Select project</option>${projects.map(p=>`<option value="${esc(p.project)}" ${w?.project===p.project?'selected':''}>${esc(p.project)}</option>`).join('')}</select></div><div class="field"><label>Project Type *</label><input id="wProjectType" list="workProjectTypes" value="${esc(w?.projectType||'')}" placeholder="Enter project type"><datalist id="workProjectTypes">${projectTypes.map(v=>`<option value="${esc(v)}">`).join('')}</datalist></div><div class="field"><label>Branch Code *</label><select id="wCode"><option value="">Select branch code</option></select></div></div></section><section class="work-section"><div class="work-section-title"><b>2</b><div><h4>Location Details</h4><p>Paste a Google Maps link to extract location details.</p></div></div><div class="form-grid"><div class="field full"><label>Google Maps Link</label><div class="inline-field"><input id="wMaps" value="${esc(w?.maps||'')}" placeholder="Paste Google Maps link"><button class="btn secondary" type="button" data-action="extract-location">Extract Location</button></div></div><div class="field"><label>State *</label><input id="wState" value="${esc(w?.state||'')}"></div><div class="field"><label>Longitude</label><input id="wLongitude" value="${esc(w?.longitude||'')}" inputmode="decimal"></div><div class="field"><label>Latitude</label><input id="wLatitude" value="${esc(w?.latitude||'')}" inputmode="decimal"></div></div></section><section class="work-section"><div class="work-section-title"><b>3</b><div><h4>SIM Card Details</h4><p>Enter the SIM provider name and card number.</p></div></div><div class="form-grid"><div class="field"><label>SIM Name *</label><input id="wSimName" value="${esc(w?.simName||'')}"></div><div class="field"><label>SIM Card Number *</label><input id="wSimNumber" value="${esc(w?.simNumber||'')}"></div></div></section><section class="work-section"><div class="work-section-title"><b>4</b><div><h4>Network / Link Details</h4></div></div><div class="form-grid"><div class="field"><label>Link IP</label><input id="wLinkIp" value="${esc(w?.linkIp||'')}"></div><div class="field"><label>Link Device MAC ID</label><input id="wMac" value="${esc(w?.mac||'')}"></div></div></section><section class="work-section"><div class="work-section-title"><b>5</b><div><h4>Site / Door TAM Details</h4></div></div><div class="form-grid tam-grid">${[['Vault TAM','wVaultTam'],['Cash Counter TAM','wCashTam'],['Main Door TAM','wMainDoorTam'],['NGL Main Door TAM','wNglDoorTam']].map(([label,input])=>`<div class="field"><label>${label}</label><select id="${input}"><option value="">Select</option><option ${w?.[input]==='OK'?'selected':''}>OK</option><option ${w?.[input]==='Faulty'?'selected':''}>Faulty</option><option ${w?.[input]==='N/A'?'selected':''}>N/A</option></select></div>`).join('')}</div></section><section class="work-section"><div class="work-section-title"><b>6</b><div><h4>Timing</h4></div></div><div class="form-grid"><div class="field"><label>In Time</label><input id="wInTime" type="time" value="${esc(w?.inTime||'')}"></div><div class="field"><label>Out Time</label><input id="wOutTime" type="time" value="${esc(w?.outTime||'')}"></div></div></section><section class="work-section"><div class="work-section-title"><b>7</b><div><h4>Engineer / QC Details</h4></div></div><div class="form-grid"><div class="field"><label>Call Taken By</label><input id="wCallTakenBy" value="${esc(w?.callTakenBy||currentUser()?.name||'')}"></div><div class="field"><label>Engineer Name</label><select id="wEng">${db.users.filter(u=>u.status==='Active').map(u=>`<option ${w?.engineer===u.name?'selected':''}>${esc(u.name)}</option>`).join('')}</select></div><div class="field"><label>Engineer Number</label><input id="wEngineerNumber" value="${esc(w?.engineerNumber||'')}" inputmode="numeric"></div><div class="field"><label>Soft QC</label><select id="wSoftQc"><option value="">Select</option><option ${w?.softQc==='Pass'?'selected':''}>Pass</option><option ${w?.softQc==='Fail'?'selected':''}>Fail</option><option ${w?.softQc==='N/A'?'selected':''}>N/A</option></select></div><div class="field"><label>Configure Status</label><select id="wConfigureStatus"><option value="">Select</option><option ${w?.configureStatus==='Configured'?'selected':''}>Configured</option><option ${w?.configureStatus==='Pending'?'selected':''}>Pending</option><option ${w?.configureStatus==='N/A'?'selected':''}>N/A</option></select></div></div></section><section class="work-section"><div class="work-section-title"><b>8</b><div><h4>Final Site Details</h4></div></div><div class="form-grid"><div class="field full"><label>Site Remark</label><textarea id="wSiteRemark">${esc(w?.siteRemark||w?.remark||'')}</textarea></div><div class="field"><label>Handover Status</label><select id="wHandover"><option value="">Select</option><option ${w?.handover==='Completed'?'selected':''}>Completed</option><option ${w?.handover==='Pending'?'selected':''}>Pending</option><option ${w?.handover==='N/A'?'selected':''}>N/A</option></select></div><div class="field"><label>Work Status *</label><select id="wStatus">${CONFIG.workStatuses.map(v=>`<option ${w?.status===v||(!w&&v==='Pending')?'selected':''}>${v}</option>`).join('')}</select></div></div></section></div><div class="actions"><button class="btn secondary" data-action="close-modal">Cancel</button><button class="btn" data-action="save-work" data-id="${id||''}">Save Daily Work</button></div>`);if(w)refreshBranches(w.project,w.code);else refreshBranches()}
async function extractWorkLocation(){const value=$('wMaps')?.value.trim()||'',match=value.match(/@(-?\d+(?:\.\d+)?),\s*(-?\d+(?:\.\d+)?)/)||value.match(/[?&](?:query|q)=(-?\d+(?:\.\d+)?),\s*(-?\d+(?:\.\d+)?)/);if(!match)return notify('Could not find latitude and longitude in that Google Maps link.','error');const latitude=match[1],longitude=match[2];$('wLatitude').value=latitude;$('wLongitude').value=longitude;$('wState').value='Looking up state...';try{const response=await fetch(`https://nominatim.openstreetmap.org/reverse?format=jsonv2&lat=${encodeURIComponent(latitude)}&lon=${encodeURIComponent(longitude)}&zoom=10&addressdetails=1`,{headers:{Accept:'application/json'}});if(!response.ok)throw Error('Reverse lookup failed');const result=await response.json(),address=result.address||{},state=address.state||address.state_district||address.region||'';if(!state)throw Error('State not found');$('wState').value=state;notify('Location and state extracted.')}catch(error){$('wState').value='';notify('Coordinates extracted, but state lookup failed. Enter the state manually.','error')}}
function saveWork(id){const values={date:$('wDate').value,engineer:$('wEng').value,project:$('wProject').value,code:$('wCode').value,branch:$('wBranch')?.value||db.projects.find(p=>p.project===$('wProject').value)?.branch||'',type:$('wType').value,status:$('wStatus').value,remark:$('wSiteRemark').value.trim(),srNo:$('wSrNo').value.trim(),projectType:$('wProjectType').value.trim(),maps:$('wMaps').value.trim(),state:$('wState').value.trim(),longitude:$('wLongitude').value.trim(),latitude:$('wLatitude').value.trim(),simName:$('wSimName').value.trim(),simNumber:$('wSimNumber').value.trim(),linkIp:$('wLinkIp').value.trim(),mac:$('wMac').value.trim(),wVaultTam:$('wVaultTam').value,wCashTam:$('wCashTam').value,wMainDoorTam:$('wMainDoorTam').value,wNglDoorTam:$('wNglDoorTam').value,inTime:$('wInTime').value,outTime:$('wOutTime').value,callTakenBy:$('wCallTakenBy').value.trim(),engineerNumber:$('wEngineerNumber').value.trim(),softQc:$('wSoftQc').value,configureStatus:$('wConfigureStatus').value,siteRemark:$('wSiteRemark').value.trim(),handover:$('wHandover').value};const missing=['date','engineer','project','code','type','status'].filter(k=>!values[k]);if(missing.length){notify(`Complete: ${missing.join(', ')}.`,'error');return}const record={id:id||uid('work'),...values,profileId:findProfileId(values.engineer)};if(id){const old=db.work.find(x=>x.id===id);Object.assign(old,record);activity(`updated daily work for ${record.project}`)}else{db.work.push(record);activity(`added daily work for ${record.project}`)}saveDatabase();closeModal();renderDaily();notify('Daily work saved.')}
