saveUser=async function(id){if(!allow(id?'userEdit':'userCreate'))return;const old=db.users.find(x=>x.id===id),email=window.TeamOpsAuth?.normalizeEmail($('uEmail').value),designation=$('uDesignation').value.trim(),record={id:id||uid('user'),profileId:old?.id||'',employeeId:$('uLogin').value.trim(),name:$('uName').value.trim(),loginId:$('uLogin').value.trim(),role:$('uRole').value,designation,department:$('uDepartment').value.trim(),project:$('uProject').value.trim(),mobile:$('uMobile').value.replace(/\D/g,'').replace(/^91(\d{10})$/,'$1'),email,status:$('uStatus').value,emailVerified:old?.email===email?Boolean(old.emailVerified):false,lastLoginAt:old?.lastLoginAt||'',createdAt:old?.createdAt||now(),updatedAt:now(),createdBy:old?.createdBy||currentUser()?.name||'System'};const errors=[];if(!record.name||!record.employeeId||!record.email)errors.push('Name, Employee ID and authorized email are required.');if(!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(record.email))errors.push('Enter a valid email address.');if(!['Admin','Assistant Manager','Team Lead','Employee'].includes(record.role))errors.push('Invalid employee role.');if(db.users.some(x=>x.id!==id&&window.TeamOpsAuth.normalizeEmail(x.email)===record.email))errors.push('This authorized email is already assigned to another employee.');if(db.users.some(x=>x.id!==id&&(x.employeeId||x.loginId).toLowerCase()===record.employeeId.toLowerCase()))errors.push('Employee ID already exists.');if(errors.length){notify(errors.join(' '),'error');return}try{if(!window.TeamOpsAuth?.configured())throw Error('Supabase is not configured. Connect Supabase before adding employees.');const payload={fullName: record.name, employeeId: record.employeeId, email: record.email, accessRole: record.role, designation: record.designation || undefined, department: record.department, project: record.project, mobile: record.mobile, status: record.status, emailVerified: record.emailVerified};const result=await window.TeamOpsAuth.provisionEmployee(payload);record.id=result.profile.id;record.profileId=result.profile.id;record.designation=designation;if(id)Object.assign(old,record);else db.users.push(record);saveDatabase();closeModal();renderTeam();notify('Employee identity and profile saved.')}catch(error){notify(error.message||'Employee provisioning failed. No local employee was saved.','error')}};
