	init();document.addEventListener('click',e=>{const target=e.target.closest('[data-action]');if(!target)return;const action=target.dataset.action,id=target.dataset.id;if(action==='open-hardware')openHardware();if(action==='save-hardware')saveHardware(id);if(action==='export-hardware')exportCollection('hardware',['Material','Hardware Name','Branch Site','Issue','Status'],['material','name','branch','issue','status'],'Hardware_Faults');if(action==='edit-hardware')openHardware(id);if(action==='delete-hardware')removeHardware(id)});setTimeout(()=>{if(simBackend())syncSimFromSupabase()},0);